package dev.pocketengine.core;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.junit.Test;import static org.junit.Assert.*;
public final class NativeToolObservationTest {
 private static final String TASK=UUID.randomUUID().toString(),RUN=UUID.randomUUID().toString();
 private static RunControl control(){RunControl original=new RunControl();original.bindHostRun(TASK,RUN,1);return original;}
 private static NativeToolObservation.Identity identity(){return new NativeToolObservation.Identity(TASK,RUN,1,"actual-profile",1,"private","actual-session","actual-space","tab",1,1,"document","observation",1,new NativeToolObservation.Viewport(100,200,0,5,1,new NativeToolObservation.Crop(0,0,100,100),100,100));}
 @Test public void onlyOriginalControlAndOperationCanConsumeOnceAndCloseRemovesPixels()throws Exception{RunControl original=control();byte[] source={1,2,3};NativeToolObservation value=NativeToolObservation.capture("browser_task_observe_visual","actual-op",original,identity(),source,"image/png",()->{});Arrays.fill(source,(byte)9);assertThrows(SecurityException.class,()->value.consume("browser_task_observe_visual","actual-op",control()));assertThrows(SecurityException.class,()->value.consume("browser_task_observe_visual","wrong-op",original));var image=value.consume("browser_task_observe_visual","actual-op",original);assertEquals("AQID",image.base64(original));assertFalse(image.metadata().getBoolean("coordinateAuthority"));assertFalse(image.metadata().getBoolean("verified"));assertFalse(image.metadata().toString().contains("AQID"));assertThrows(SecurityException.class,()->value.consume("browser_task_observe_visual","actual-op",original));value.close();assertThrows(IllegalStateException.class,()->image.base64(original));}
 @Test public void nativeCurrentnessCallbacksNeverHoldCarrierOrImageMonitorDuringClose()throws Exception{RunControl original=control();AtomicReference<NativeToolObservation> holder=new AtomicReference<>();AtomicBoolean block=new AtomicBoolean();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);NativeToolObservation value=NativeToolObservation.capture("browser_task_observe_visual","actual-op",original,identity(),new byte[]{1,2,3},"image/png",()->{if(holder.get()!=null)assertFalse(Thread.holdsLock(holder.get()));if(block.get()){entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));}});holder.set(value);var image=value.consume("browser_task_observe_visual","actual-op",original);block.set(true);ExecutorService worker=Executors.newSingleThreadExecutor();try{Future<?> pending=worker.submit(()->assertThrows(Exception.class,()->image.base64(original)));assertTrue(entered.await(3,TimeUnit.SECONDS));value.close();release.countDown();pending.get(3,TimeUnit.SECONDS);}finally{release.countDown();worker.shutdownNow();assertTrue(worker.awaitTermination(3,TimeUnit.SECONDS));value.close();}}
 @Test public void revokedNativeFrameCannotBeConvertedIntoImageEvenWithSameToolJson()throws Exception{RunControl original=control();AtomicBoolean current=new AtomicBoolean(true);NativeToolObservation value=NativeToolObservation.capture("browser_task_observe_visual","actual-op",original,identity(),new byte[]{1},"image/jpeg",()->{if(!current.get())throw new SecurityException("actual_native_document_changed");});current.set(false);assertThrows(SecurityException.class,()->value.consume("browser_task_observe_visual","actual-op",original));value.close();}
 @Test public void nativeMimeBoundsAndCropAreExplicitRatherThanAJsonScreenshotClaim()throws Exception{RunControl original=control();assertThrows(IllegalArgumentException.class,()->NativeToolObservation.capture("browser_task_observe_visual","op",original,identity(),new byte[]{1},"application/octet-stream",()->{}));assertThrows(IllegalArgumentException.class,()->new NativeToolObservation.Viewport(100,100,0,0,1,new NativeToolObservation.Crop(99,0,2,10),2,10));assertThrows(IllegalArgumentException.class,()->NativeToolObservation.capture("browser_task_observe_visual","op",original,identity(),new byte[0],"image/png",()->{}));}
 private static NativeToolObservation.ProjectImageIdentity project(byte[] bytes)throws Exception{StringBuilder sha=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(bytes))sha.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return new NativeToolObservation.ProjectImageIdentity(TASK,RUN,1,UUID.randomUUID().toString(),UUID.randomUUID().toString(),"asset.png","","checkout_file","a".repeat(64),sha.toString(),"image/png",bytes.length,1,1,1);}
 private static org.json.JSONArray request(NativeToolObservation.Image image,String encoded)throws Exception{return new org.json.JSONArray().put(new org.json.JSONObject().put("role","user").put("content",new org.json.JSONArray().put(new org.json.JSONObject().put("type","text").put("text",image.metadata().toString())).put(new org.json.JSONObject().put("type","image_url").put("image_url",new org.json.JSONObject().put("url","data:image/png;base64,"+encoded)))));}
 @Test public void projectCarrierChecksActualDigestAndOnlyTheOriginalReadCallConsumes()throws Exception{RunControl original=control();byte[] bytes={1,2,3};var identity=project(bytes);assertThrows(SecurityException.class,()->NativeToolObservation.captureProject("image-op",original,identity,new byte[]{3,2,1},()->{}));try(var value=NativeToolObservation.captureProject("image-op",original,identity,bytes,()->{})){assertThrows(SecurityException.class,()->value.consume("browser_task_observe_visual","image-op",original));var image=value.consume("project_view_image","image-op",original);assertEquals("project_image_snapshot",image.metadata().getString("kind"));assertEquals(identity.sha256(),image.metadata().getString("sha256"));assertThrows(SecurityException.class,()->value.consume("project_view_image","image-op",original));image.close();}}
 @Test public void projectDispatchPinKeepsLiveSourceAfterPixelsAreErasedAndCannotBeMintedFromAnotherBody()throws Exception{RunControl original=control();AtomicBoolean allowed=new AtomicBoolean(true);try(var value=NativeToolObservation.captureProject("image-op",original,project(new byte[]{1}),new byte[]{1},()->{if(!allowed.get())throw new SecurityException("source_withdrawn");})){var image=value.consume("project_view_image","image-op",original);String encoded=image.base64(original);assertThrows(SecurityException.class,()->image.retainProjectRequest(original,"Ag=="));var wire=request(image,encoded);try(var pin=image.retainProjectRequest(original,encoded)){image.close();assertThrows(IllegalStateException.class,()->image.base64(original));assertTrue(pin.presentIn(new org.json.JSONArray(wire.toString())));pin.requireCurrent(original);allowed.set(false);assertThrows(SecurityException.class,()->pin.requireCurrent(original));assertThrows(SecurityException.class,()->pin.requireCurrent(control()));}}}
 @Test public void projectPinsDistinguishIdenticalPixelsFromDifferentNativeObservations()throws Exception{RunControl original=control();try(var a=NativeToolObservation.captureProject("one",original,project(new byte[]{1}),new byte[]{1},()->{});var b=NativeToolObservation.captureProject("two",original,project(new byte[]{1}),new byte[]{1},()->{})){var first=a.consume("project_view_image","one",original);var second=b.consume("project_view_image","two",original);String bytes=first.base64(original);try(var old=first.retainProjectRequest(original,bytes);var fresh=second.retainProjectRequest(original,bytes)){var wire=request(second,bytes);assertFalse(old.presentIn(wire));assertTrue(old.includesBytes(wire));assertTrue(old.sameNativeBytes(fresh));assertTrue(fresh.presentIn(wire));wire.getJSONObject(0).getJSONArray("content").getJSONObject(0).put("text","metadata alone is not native provenance");assertFalse(fresh.presentIn(wire));assertTrue(fresh.includesBytes(wire));}}}
 @Test public void projectPinRejectsPauseResumeAndCancelErasesConsumedPixels()throws Exception{RunControl original=control();try(var value=NativeToolObservation.captureProject("one",original,project(new byte[]{1}),new byte[]{1},()->{})){var image=value.consume("project_view_image","one",original);try(var pin=image.retainProjectRequest(original,image.base64(original))){original.pause();original.resume();assertThrows(SecurityException.class,()->pin.requireCurrent(original));original.cancel();assertThrows(IllegalStateException.class,()->image.base64(original));}}}
}
